def chunk_overlap(text: str, max_len: int, overlap: int) -> list:
    if max_len <= 0:
        return []

    if not text:
        return []

    if len(text) <= max_len:
        return [text]

    if overlap < 0 or overlap >= max_len:
        return []

    step = max_len - overlap
    chunks = []
    start = 0
    n = len(text)

    while start < n:
        end = min(start + max_len, n)
        chunks.append(text[start:end])
        if end == n:
            break
        start += step

    return chunks

